function changeQuantity(input){const key=input.dataset.quantity,max=Number(input.max),qty=Math.min(max,Math.max(1,Math.floor(Number(input.value)||1)));input.value=qty;const control=input.closest('.quantity');$('[data-delta="-1"]',control).disabled=qty<=1;$('[data-delta="1"]',control).disabled=qty>=max;if(key==='product')return;const l=state.cart.find(x=>x.key===key);if(!l)return;const p=getProduct(l.id),others=state.cart.filter(x=>x.id===l.id&&x.key!==key).reduce((n,x)=>n+x.qty,0);l.qty=Math.min(qty,p.stock-others);persist();if(location.hash==='#checkout')$('#main').innerHTML=checkout();showCart()}
document.addEventListener('input',e=>{if(e.target.id==='search-input'){const q=e.target.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();$('#search-results').innerHTML=searchResults(products.filter(p=>[p.name,p.brand,p.material,categories[p.category]].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)))}if(e.target.name==='weight'&&$('#weight-label'))$('#weight-label').textContent=e.target.value});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.quantity)changeQuantity(t);if(t.id==='sort'){sort=t.value;render(false)}if(t.id==='per-page'){visibleCount=Number(t.value);render(false)}if(t.id==='company-toggle'){$('#company-fields').hidden=!t.checked;$$('input',$('#company-fields')).forEach(x=>x.required=t.checked)}if(t.id==='different-address'){$('#different-address-field').hidden=!t.checked;$('textarea',$('#different-address-field')).required=t.checked}if(t.id==='surface')selectedSurface=t.value;if(t.id==='warranty')selectedWarranty=Number(t.value);if(t.id==='use-points'){checkoutData.usePoints=t.checked;render(false)}if(['shipping','payment'].includes(t.name)&&t.closest('[data-form="checkout-delivery"]')){const fd=new FormData(t.form);Object.assign(checkoutData,Object.fromEntries(fd));render(false)}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),kind=form.dataset.form;if(form.id==='newsletter'){toast('Děkujeme! Ukázkový odběr je připravený. E-mail se neodeslal.');form.reset();return}if(form.id==='cookie-form'){saveConsent(fd.has('analytics'),fd.has('marketing'));return}if(form.id==='coupon-form'){const value=String(fd.get('coupon')).trim().toUpperCase();if(!['BRAVE5','JARO2026',''].includes(value)){toast('Kód neznáme. Vyzkoušejte BRAVE5.');return}coupon=value;render(false);toast(value?'Slevový kód byl použit.':'Slevový kód byl odebrán.');return}if(form.id==='chat-form'){chatAnswer(String(fd.get('message')));form.reset();return}if(kind==='quick-add'){addToCart(form.dataset.id,fd.get('qty'),fd.get('color'),fd.get('surface'),fd.get('warranty'));return}if(kind==='currency'){state.currency=fd.get('currency');persist();$('#modal').close();render(false);return}if(['login','register','profile'].includes(kind)){state.user={name:String(fd.get('name')||String(fd.get('email')).split('@')[0]),email:String(fd.get('email'))};persist();$('#modal').close();location.hash='#account';if(location.hash==='#account')render();toast('Ukázkový účet je připravený.');return}if(kind==='reset'){toast('Ukázka obnovy dokončena. Žádný e-mail se neodeslal.');$('#modal').close();return}if(kind==='checkout-delivery'){Object.assign(checkoutData,Object.fromEntries(fd));checkoutStep=2;render();return}if(kind==='checkout-contact'){Object.assign(checkoutData,Object.fromEntries(fd));if(!$('#company-toggle').checked){checkoutData.company='';checkoutData.ico=''}if(!$('#different-address').checked)checkoutData.deliveryAddress='';checkoutStep=3;render();return}if(kind==='checkout-complete'){const total=cartTotal(),delivery=checkoutData.shipping==='pickup'||total>=1990?0:checkoutData.shipping==='point'?79:149,discount=coupon==='BRAVE5'?Math.round(total*.05):coupon==='JARO2026'?Math.round(total*.4):0,points=state.orders.reduce((n,o)=>n+o.points,0),used=checkoutData.usePoints&&state.user?Math.min(points,total-discount):0,final=total+delivery+(checkoutData.payment==='cod'?49:0)-discount-used,number='BRV-'+String(Date.now()).slice(-7);state.orders.unshift({number,date:new Date().toLocaleDateString('cs-CZ'),total:final,points:Math.floor(final/100)-used,items:state.cart.map(l=>({...l}))});state.cart=[];checkoutData={};coupon='';checkoutStep=1;persist();$('#main').innerHTML=`${pageTop('Tady začíná nový příběh.','','DĚKUJEME')}<section class="section" style="text-align:center"><h2>Ukázková objednávka<br>je dokončená.</h2><p>Číslo ${number} · ${currency(final)}</p><p class="muted">Žádná platba ani skutečná objednávka nevznikla.<br>Přehled najdete v ukázkovém účtu v tomto prohlížeči.</p><a class="btn dark" href="#catalog/all">Zpátky k inspiraci ↗</a></section>`;window.scrollTo({top:0,behavior:'instant'});return}if(kind){toast(kind==='watch'?'Hlídání ceny je vyzkoušeno. Žádná služba ani e-mail se neaktivovaly.':kind==='reservation'?'Ukázka rezervace dokončena. Termín nebyl skutečně rezervován.':'Děkujeme. Formulář funguje, údaje se nikam neodeslaly.');form.reset();if($('#modal').open)$('#modal').close();}});
$('#overlay').addEventListener('click',closeDrawer);$('#modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();$('#mega-menu').hidden=true;$('#cursor').classList.remove('visible')}if(e.key==='Tab'&&!$('#drawer').hidden){const focusables=$$('button,a[href],input:not([disabled]),select,textarea',$('#drawer')),first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let announcementIndex=0;const announcements=['Doprava zdarma při nákupu nad 1 990 Kč','Ukázkový kód BRAVE5 · 5 % na váš první nákup','Za každý nákup body do věrnostního programu','Vybrané kousky pro domov i zahradu'];
document.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const cursor=$('#cursor'),target=e.target.closest('[data-cursor]');cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';cursor.classList.toggle('visible',!!target);if(target)cursor.textContent=target.dataset.cursor});document.addEventListener('pointerleave',()=>$('#cursor').classList.remove('visible'));
let megaTimer;$$('.category-nav a').forEach(a=>{a.addEventListener('mouseenter',()=>{clearTimeout(megaTimer);const cat=a.hash.split('/')[1];if(!subcategories[cat])return;const menu=$('#mega-menu');menu.innerHTML=`<div><p class="eyebrow">${categories[cat]}</p>${subcategories[cat].map(s=>`<a href="#catalog/${cat}" data-subtype="${s}">${s} ↗</a>`).join('')}</div><div><p class="eyebrow">NECHTE SE INSPIROVAT</p><a href="#page/blog">Příběhy o bydlení ↗</a><a href="#page/poradna">Pomůžeme s výběrem ↗</a><a href="#catalog/${cat}">Prohlédnout vše ↗</a></div><a href="#catalog/${cat}">${img(THEME.categoryImages?.[cat]||(cat==='living'?'living':cat==='bedroom'?'bedroom':cat==='dining'?'dining':cat==='office'?'office':cat==='garden'?'garden':'shelf'),categories[cat])}</a>`;menu.hidden=false});a.addEventListener('mouseleave',()=>{megaTimer=setTimeout(()=>$('#mega-menu').hidden=true,180)})});$('#mega-menu').addEventListener('mouseenter',()=>clearTimeout(megaTimer));$('#mega-menu').addEventListener('mouseleave',()=>$('#mega-menu').hidden=true);
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link){const subtype=link.dataset.subtype;$('#modal').close();$('#mega-menu').hidden=true;if(link.hash.startsWith('#catalog/')){if(subtype)typeFilter=subtype;else if(link.hash!==location.hash)typeFilter='';if(link.hash!==location.hash){filters={};visibleCount=12}}if(link.hash===location.hash){closeDrawer();if(subtype)render();}}});

let heroVideoObserver;
const heroMotionQuery=window.matchMedia('(min-width: 761px) and (prefers-reduced-motion: no-preference)');
function heroVideoAllowed(){return heroMotionQuery.matches&&!navigator.connection?.saveData;}
function setupHeroVideo(){
 heroVideoObserver?.disconnect();
 const video=$('.hero-video'),toggle=$('.hero-video-toggle');
 if(!video||!toggle)return;
 video.muted=true;
 const play=()=>{if(video.dataset.userPaused!=='true'&&!document.hidden&&heroVideoAllowed())video.play().catch(()=>{toggle.hidden=true;});};
 video.addEventListener('playing',()=>{video.classList.add('is-ready');toggle.hidden=false;});
 video.addEventListener('error',()=>{video.classList.remove('is-ready');toggle.hidden=true;});
 toggle.addEventListener('click',()=>{
  const pause=video.dataset.userPaused!=='true';video.dataset.userPaused=String(pause);
  if(pause)video.pause();else play();
  toggle.innerHTML=pause?'▶ <span>Přehrát video</span>':'Ⅱ <span>Pozastavit video</span>';
  toggle.setAttribute('aria-label',pause?'Přehrát video na pozadí':'Pozastavit video na pozadí');
 });
 heroVideoObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting)play();else video.pause();}},{threshold:.05});
 heroVideoObserver.observe(video);
 play();
}
document.addEventListener('visibilitychange',()=>{
 const video=$('.hero-video');if(!video)return;
 if(document.hidden)video.pause();else if(video.dataset.userPaused!=='true'&&heroVideoAllowed()&&video.getBoundingClientRect().bottom>0)video.play().catch(()=>{});
});
heroMotionQuery.addEventListener('change',()=>{if($('.hero')){$('.hero').outerHTML=hero();setupHeroVideo();}});

window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#product/')){selectedColor='Písková';selectedSurface='Saténový';selectedWarranty=5}render()});
